def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    obstacles = observation['obstacles']
    resources = observation['resources']
    remaining = observation['remaining_resource_count']
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > px:
            dx = 1
        elif target_x < px:
            dx = -1
        if target_y > py:
            dy = 1
        elif target_y < py:
            dy = -1
        if (px + dx, py + dy) in obstacles:
            dx, dy = 0, 0
        return [dx, dy]

    if resources:
        target = min(resources, key=lambda r: abs(r[0]-px)+abs(r[1]-py))
        return move_towards(target[0], target[1])

    if remaining > 0:
        return [0, 0]

    to_opp_x = opp_x - px
    to_opp_y = opp_y - py
    dx, dy = 0, 0
    if abs(to_opp_x) + abs(to_opp_y) > 0:
        dx = 1 if to_opp_x > 0 else -1 if to_opp_x < 0 else 0
        dy = 1 if to_opp_y > 0 else -1 if to_opp_y < 0 else 0
        if (px + dx, py + dy) in obstacles:
            dx, dy = 0, 0
    return [dx, dy]
